--
-- Updating data of table SUserInterface.DropDownListDefinitions
--
PRINT(N'Updating data of table SUserInterface.DropDownListDefinitions')
GO
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'SELECT  olfu.Label AS Name,
        root_hobt.Guid
FROM    SUserInterface.GridViewDefinitions root_hobt
OUTER APPLY	SCore.ObjectLabelForUser(root_hobt.LanguageLabelId,[[UserId]]) olfu
WHERE root_hobt.Guid = [[ParentGuid]]' WHERE ID = 13
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'SELECT	
		root_hobt.Guid,
		root_hobt.Name
FROM	SFin.CreditTerms root_hobt' WHERE ID = 69
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'SELECT	root_hobt.Guid,
		root_hobt.Name
FROM	SJob.JobPaymentStages_List root_hobt
JOIN	SJob.Jobs			AS j ON (j.ID	= root_hobt.JobID)
JOIN	SFin.Transactions	AS t ON (t.JobID = j.ID)
WHERE	(t.Guid = ''[[ParentGuid]]'')
	AND (root_hobt.RowStatus NOT IN (0, 254))' WHERE ID = 76
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'
SELECT root_hobt.Name, root_hobt.Guid
FROM SFin.InvoiceSchedules AS root_hobt
JOIN SFin.InvoiceScheduleTrigger AS It ON (It.ID = root_hobt.TriggerId)
JOIN SSop.Quotes AS q ON (q.ID = root_hobt.QuoteId)
WHERE 
		(q.Guid = [[ParentGuid]])
	AND (root_hobt.RowStatus NOT IN (0,254))' WHERE ID = 104
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'SELECT 
    root_hobt.Guid,
    root_hobt.FullName AS Name
FROM SCore.Identities AS root_hobt
WHERE root_hobt.OriganisationalUnitId = (
    SELECT OriganisationalUnitId
    FROM SCore.Identities
    WHERE ID = [[UserId]]
)
AND root_hobt.IsActive = 1' WHERE ID = 112
UPDATE SUserInterface.DropDownListDefinitions SET SqlQuery = N'Select root_hobt.Guid, CONCAT(root_hobt.Description, N'' - '', CONVERT(NVARCHAR(7),root_hobt.VatPercentage)) AS Description
FROM SFin.VatCodes root_hobt
WHERE (root_hobt.Active = 1)' WHERE ID = 114

--
-- Updating data of table SUserInterface.GridViewDefinitions
--
PRINT(N'Updating data of table SUserInterface.GridViewDefinitions')
GO
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT	ID,
		Guid,
		RowStatus,
		Number,
		RealNet AS Net,
		RealVat AS Vat,
		RealGross AS Gross,
		RealOutstanding AS Outstanding,
		Date,
		Type,
		Surveyor,
		SageTransactionReference,
		RealOutstanding,
		RealOutstandingWithVAT,
		FinanceAccount,
		TransactionStatus
FROM	SJob.tvf_JobTransactions([[UserId]], ''[[ParentGuid]]'') root_hobt' WHERE ID = 89
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT	root_hobt.ID,
		root_hobt.RowStatus,
		root_hobt.RowVersion,
		root_hobt.Guid,
		root_hobt.CreatedDateTime,
		root_hobt.TotalRibaStageChange,
		root_hobt.FeeCapChange,
		root_hobt.FullName,
               root_hobt.TotalMeetingChange,
               root_hobt.TotalVisitChange,
               root_hobt.Reason
FROM	SJob.tvf_FeeAmendments([[UserId]], ''[[ParentGuid]]'') root_hobt' WHERE ID = 114
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT
     root_hobt.ID,
     root_hobt.RowStatus,
     root_hobt.Guid,
     root_hobt.Notes,
     root_hobt.CreatedDateTimeUTC,
     root_hobt.RequesterUserId,
     root_hobt.JobId,
     root_hobt.SurveyorName,
     root_hobt.Number,
     root_hobt.FinanceAccountID,
     root_hobt.FinanceAccountName,
     root_hobt.FinanceAccountCode,
     root_hobt.HasFinanceAccountIssue,
     root_hobt.FinanceAccountIssueMessage,
     -- [CBLD-522]
     root_hobt.ActivityId,
     -- [CBLD-525]
     root_hobt.ClientName,
     root_hobt.Net,
     root_hobt.EndDate,
     root_hobt.JobBillingInstruction,
     root_hobt.CRMBillingInstruction,
     root_hobt.IsBillable,
     root_hobt.OrgUnit,
     root_hobt.InvoicingType,
     root_hobt.ExpectedDate,
     root_hobt.ManualStatus,
     root_hobt.HasBatchingIssue,
     root_hobt.BatchingIssueMessage
FROM [SFin].[tvf_InvoiceRequests]([[UserId]]) AS root_hobt' WHERE ID = 168
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT * 
FROM [SCore].[WorkflowStatus] root_hobt
WHERE 
	(root_hobt.RowStatus NOT IN (0,254)) AND
	( NOT EXISTS --Exclude system generated statuses.
			(
				SELECT 1 
				FROM [SCore].[WorkflowStatus]
				WHERE 
					ShowInEnquiries = 0 AND
					ShowInQuotes = 0 AND
					ShowInJobs = 0 AND
					root_hobt.ID = ID
			)
	)' WHERE ID = 210
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT
 *
FROM
      [SFin].[tvf_AutomatedInvoicing]([[UserId]]) root_hobt' WHERE ID = 215
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT 
		root_hobt.ID,
		root_hobt.RowStatus,
		root_hobt.RowVersion,
		root_hobt.Guid,
		root_hobt.Name,
		root_hobt.DescriptionOfWork,
		root_hobt.Amount,
		root_hobt.TriggerId,
                root_hobt.ExpectedDate,
                root_hobt.IsSystemGeneratedManual
FROM [SFin].[tvf_JobInvoiceSchedules]([[UserId]], [[ParentGuid]]) AS root_hobt' WHERE ID = 219
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT  * 
FROM [SSop].[tvf_ApprovedEnquiries] ([[UserId]]) root_hobt' WHERE ID = 237
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'SELECT 
		root_hobt.ID,
		root_hobt.Guid,
		root_hobt.RowVersion,
		root_hobt.SageVatNo,
		root_hobt.Description,
		root_hobt.VatPercentage,
		root_hobt.EffectiveFromDate,
		root_hobt.Active
FROM SFin.VatCodes AS root_hobt' WHERE ID = 251
UPDATE SUserInterface.GridViewDefinitions SET SqlQuery = N'  SELECT 
	 root_hobt.[ID]
    ,root_hobt.[RowStatus]
    ,root_hobt.[RowVersion]
    ,root_hobt.[Guid]
    ,root_hobt.[Name]
    ,root_hobt.[DueDays]
FROM [SFin].[CreditTerms] AS root_hobt
WHERE root_hobt.RowStatus NOT IN (0,254)
           AND root_hobt.Guid <> N''00000000-0000-0000-0000-000000000000''' WHERE ID = 253

